225	    /**
226	     * Resolves the city name to use for a newly created owner. The supplied city is
227	     * title-cased (each whitespace-separated word starts with an upper-case letter and the
228	     * remaining letters are lower-cased), for example {@code "new york"} becomes
229	     * {@code "New York"}. However, if an owner already exists in that city (matched ignoring
230	     * letter case), the existing owner's exact spelling of the city name is reused instead, so
231	     * that all owners in a city share a single canonical spelling.
232	     *
233	     * @param city the city supplied for the owner being created, may be {@code null}
234	     * @return the city name to store and return for the owner
235	     */
236	    private String resolveCity(String city) {
237	        if (city == null) {
238	            return null;
239	        }
240	        String existingCity = this.clinicService.findAllOwners().stream()
241	            .map(Owner::getCity)
242	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
243	            .findFirst()
244	            .orElse(null);
245	        if (existingCity != null) {
246	            return existingCity;
247	        }
248	        return toTitleCase(city);
249	    }
250	
251	    /**
252	     * Title-cases the given text so that each whitespace-separated word starts with an
253	     * upper-case letter and the remaining letters are lower-cased, for example
254	     * {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}. The original
255	     * spacing between words is preserved.
256	     *
257	     * @param value the text to title-case
258	     * @return the title-cased text
259	     */
260	    private static String toTitleCase(String value) {
261	        StringBuilder result = new StringBuilder(value.length());
262	        boolean startOfWord = true;
263	        for (int i = 0; i < value.length(); i++) {
264	            char ch = value.charAt(i);
265	            if (Character.isWhitespace(ch)) {
266	                startOfWord = true;
267	                result.append(ch);
268	            } else if (startOfWord) {
269	                result.append(Character.toUpperCase(ch));
270	                startOfWord = false;
271	            } else {
272	                result.append(Character.toLowerCase(ch));
273	            }
274	        }
275	        return result.toString();
276	    }
