278	    /**
279	     * Builds the customer code for a newly created owner, formatted as
280	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
281	     * owners already registered in that city, zero-padded to four digits (e.g.
282	     * {@code 'LONDON-0007'}). Cities are matched ignoring letter case so the sequence is
283	     * consistent with the upper-cased prefix.
284	     *
285	     * @param city the city of the owner being created
286	     * @return the assigned customer code
287	     */
288	    private String nextCustomerCode(String city) {
289	        long ownersInCity = this.clinicService.findAllOwners().stream()
290	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
291	            .count();
292	        return city.toUpperCase() + "-" + String.format("%04d", ownersInCity + 1);
293	    }
