295	    /**
296	     * Counts how many existing owners share the given last name at this moment. The count is taken
297	     * over the owners already registered (excluding the owner currently being created, which has not
298	     * yet been persisted); last names are compared for exact equality.
299	     *
300	     * @param lastName the last name of the owner being created
301	     * @return the number of other owners that currently share the given last name
302	     */
303	    private int countNamesakes(String lastName) {
304	        return (int) this.clinicService.findAllOwners().stream()
305	            .filter(existing -> Objects.equals(existing.getLastName(), lastName))
306	            .count();
