309	    /**
310	     * Determines whether, at the moment the owner is being created, another owner already shares
311	     * the same household &mdash; that is, an existing owner has both the same address and the same
312	     * city. Address and city are compared for exact equality, using the values resolved for the
313	     * owner being created (which has not yet been persisted).
314	     *
315	     * @param owner the candidate owner to check
316	     * @return {@code true} if an existing owner already has the same address and city
317	     */
318	    private boolean sharesHousehold(Owner owner) {
319	        return this.clinicService.findAllOwners().stream()
320	            .anyMatch(existing -> Objects.equals(existing.getAddress(), owner.getAddress())
321	                && Objects.equals(existing.getCity(), owner.getCity()));
322	    }
