324	    /**
325	     * Determines whether the maximum number of owners that may be registered on a single day has
326	     * already been reached. At most 20 owners may be created per day; the count is taken over the
327	     * owners whose registration date is today.
328	     *
329	     * @return {@code true} if 20 or more owners have already been registered today
330	     */
331	    private boolean isDailyRegistrationLimitReached() {
332	        LocalDate today = LocalDate.now();
333	        long ownersToday = this.clinicService.findAllOwners().stream()
334	            .filter(existing -> today.equals(existing.getRegistrationDate()))
335	            .count();
336	        return ownersToday >= 20;
