339	    /**
340	     * Determines whether the city of the owner being created has already reached its capacity of
341	     * owners. At most 8 owners may be registered in a single city; the count is taken over the
342	     * existing owners whose city matches (ignoring letter case) the given city.
343	     *
344	     * @param city the city of the owner being created, may be {@code null}
345	     * @return {@code true} if the city already contains 8 or more owners
346	     */
347	    private boolean isCityCapacityReached(String city) {
348	        if (city == null) {
349	            return false;
350	        }
351	        long ownersInCity = this.clinicService.findAllOwners().stream()
352	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
353	            .count();
354	        return ownersInCity >= 8;
355	    }
