357	    /**
358	     * Determines whether an owner already exists that uses the same telephone number as the
359	     * given candidate. Telephone numbers are compared digits-only, so formatting characters
360	     * such as spaces, dashes and parentheses are ignored.
361	     *
362	     * @param owner the candidate owner to check
363	     * @return {@code true} if an owner with the same telephone number already exists
364	     */
365	    private boolean isDuplicateOwner(Owner owner) {
366	        String telephone = normalizeTelephone(owner.getTelephone());
367	        return this.clinicService.findAllOwners().stream()
368	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
369	    }
