371	    /**
372	     * Determines whether an owner already exists that uses the same email address as the
373	     * given candidate. Owners without an email address are never considered duplicates.
374	     * The comparison ignores letter case and surrounding or repeated whitespace.
375	     *
376	     * @param owner the candidate owner to check
377	     * @return {@code true} if an owner with the same email address already exists
378	     */
379	    private boolean isDuplicateEmail(Owner owner) {
380	        String email = normalize(owner.getEmail());
381	        if (email == null || email.isEmpty()) {
382	            return false;
383	        }
384	        return this.clinicService.findAllOwners().stream()
385	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
386	    }
