388	    /**
389	     * Normalizes a value for duplicate detection so that comparisons ignore letter case and
390	     * surrounding or repeated whitespace. Leading and trailing whitespace is stripped, any run
391	     * of internal whitespace collapses to a single space, and the result is lower-cased. For
392	     * example {@code "  John   Smith "} and {@code "John Smith"} both normalize to
393	     * {@code "john smith"}.
394	     *
395	     * @param value the value to normalize, may be {@code null}
396	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
397	     */
398	    private static String normalize(String value) {
399	        if (value == null) {
400	            return null;
401	        }
402	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
403	    }
404	
405	    /**
406	     * Normalizes a telephone number to digits only by stripping every non-digit character
407	     * (such as spaces, dashes and parentheses). This is used both to store telephone numbers
408	     * in a canonical form and to compare them for uniqueness, so that {@code "(613) 555-0100"}
409	     * and {@code "6135550100"} are treated as the same number.
410	     *
411	     * @param value the telephone number to normalize, may be {@code null}
412	     * @return the digits-only telephone number, or {@code null} if {@code value} is {@code null}
413	     */
414	    private static String normalizeTelephone(String value) {
415	        if (value == null) {
416	            return null;
417	        }
418	        return value.replaceAll("\\D", "");
419	    }
